from collections import deque
class Solution:
    def removeOnes(self, grid):
        m, n = len(grid), len(grid[0])
        rm = [0] * m
        cm = [0] * n
        start = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    b = 1 << (i * n + j)
                    start |= b
                    rm[i] |= b
                    cm[j] |= b
        dist = {start: 0}
        q = deque([start])
        while q:
            cur = q.popleft()
            if cur == 0:
                return dist[cur]
            mm = cur
            while mm:
                b = mm & -mm
                mm ^= b
                k = b.bit_length() - 1
                i, j = divmod(k, n)
                nx = cur & ~(rm[i] | cm[j])
                if nx not in dist:
                    dist[nx] = dist[cur] + 1
                    q.append(nx)
        return 0

