class Solution {
    public int removeOnes(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] rm = new int[m], cm = new int[n];
        int start = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1) {
                    int b = 1 << (i * n + j);
                    start |= b; rm[i] |= b; cm[j] |= b;
                }
        Map<Integer, Integer> dist = new HashMap<>();
        dist.put(start, 0);
        Queue<Integer> q = new LinkedList<>();
        q.add(start);
        while (!q.isEmpty()) {
            int cur = q.poll();
            if (cur == 0) return dist.get(cur);
            for (int mm = cur; mm != 0; mm -= mm & -mm) {
                int b = mm & -mm;
                int k = Integer.numberOfTrailingZeros(b);
                int nx = cur & ~(rm[k / n] | cm[k % n]);
                if (!dist.containsKey(nx)) {
                    dist.put(nx, dist.get(cur) + 1);
                    q.add(nx);
                }
            }
        }
        return 0;
    }
}

